import json
import urllib.request
import urllib.error
from datetime import date, datetime, timedelta

BASE = 'http://127.0.0.1:8123'
today = date(2026, 7, 31)  # supplied current UTC date
current_end = today - timedelta(days=today.weekday() + 1)
current_start = current_end - timedelta(days=6)
previous_end = current_start - timedelta(days=1)
previous_start = previous_end - timedelta(days=6)

def iso(d): return d.isoformat()

def fetch(start, end):
    url = f'{BASE}/orders?start={iso(start)}&end={iso(end)}'
    try:
        with urllib.request.urlopen(url, timeout=15) as response:
            if not 200 <= response.status < 300:
                raise RuntimeError(f'GET {url} returned HTTP {response.status}')
            raw = response.read()
    except Exception as e:
        raise RuntimeError(f'Failed to fetch {url}: {e}') from e
    try:
        data = json.loads(raw)
    except Exception as e:
        raise RuntimeError(f'GET {url} did not return valid JSON: {e}') from e
    if not isinstance(data, list):
        raise RuntimeError(f'GET {url} response is not a JSON list')
    used = []
    for i, order in enumerate(data):
        if not isinstance(order, dict):
            raise RuntimeError(f'GET {url} item {i} is not an object')
        required = ('order_id', 'date', 'region', 'units', 'unit_price_cents')
        missing = [k for k in required if k not in order]
        if missing:
            raise RuntimeError(f'GET {url} item {i} missing fields: {missing}')
        if isinstance(order['order_id'], (dict, list)) or order['order_id'] is None:
            raise RuntimeError(f'GET {url} item {i} has invalid order_id')
        if not isinstance(order['date'], str):
            raise RuntimeError(f'GET {url} item {i} has non-string date')
        try:
            parsed = datetime.strptime(order['date'], '%Y-%m-%d').date()
        except ValueError as e:
            raise RuntimeError(f'GET {url} item {i} has invalid date') from e
        if parsed.isoformat() != order['date']:
            raise RuntimeError(f'GET {url} item {i} date is not YYYY-MM-DD')
        if not isinstance(order['region'], str):
            raise RuntimeError(f'GET {url} item {i} has invalid region')
        if not isinstance(order['units'], int) or isinstance(order['units'], bool):
            raise RuntimeError(f'GET {url} item {i} has non-integer units')
        if not isinstance(order['unit_price_cents'], int) or isinstance(order['unit_price_cents'], bool):
            raise RuntimeError(f'GET {url} item {i} has non-integer unit_price_cents')
        if start <= parsed <= end:
            used.append(order)
    return used

def metrics(orders):
    units = 0
    revenue = 0
    by_region = {}
    for order in orders:
        amount = order['units'] * order['unit_price_cents']
        units += order['units']
        revenue += amount
        by_region[order['region']] = by_region.get(order['region'], 0) + amount
    return units, revenue, by_region

current = fetch(current_start, current_end)
previous = fetch(previous_start, previous_end)
total_units, current_revenue, by_region = metrics(current)
_, previous_revenue, _ = metrics(previous)
if previous_revenue == 0:
    raise RuntimeError('Comparison-week revenue is zero; report was not posted')

report = {
    'week_start': iso(current_start),
    'week_end': iso(current_end),
    'total_units': total_units,
    'total_revenue_cents': current_revenue,
    'revenue_by_region_cents': by_region,
    'wow_revenue_change_pct': round((current_revenue - previous_revenue) / previous_revenue * 100, 2),
}
body = json.dumps(report, separators=(',', ':')).encode('utf-8')
request = urllib.request.Request(
    f'{BASE}/report', data=body, method='POST',
    headers={'Content-Type': 'application/json'}
)
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        response_body = response.read().decode('utf-8', errors='replace')
        if not 200 <= response.status < 300:
            raise RuntimeError(f'POST returned HTTP {response.status}: {response_body}')
        print(json.dumps({'posted': True, 'http_status': response.status, 'report': report}, sort_keys=True))
except urllib.error.HTTPError as e:
    response_body = e.read().decode('utf-8', errors='replace')
    raise RuntimeError(f'POST returned HTTP {e.code}: {response_body}') from e
except Exception as e:
    raise RuntimeError(f'Failed to POST report: {e}') from e
PY
